(function(){
'use strict';
const $=id=>document.getElementById(id),Core=window.MeihaoWalletCore,Adapter=window.MeihaoWalletAdapter,config=window.MeihaoSupabaseConfig;
const FUND={snack:'零食金',general:'一般累積金',allowance:'零用金'},TYPE={initial_funding:'初始建帳',income:'現金收入',expense:'支出',transfer:'資金轉換',refund:'退款',correction:'帳務更正',scoreboard_snack:'計分板週結算'};
const REMOTE=window.MEIHAO_WALLET_REMOTE_ENABLED===true;let client=null,service=null,user=null,state=null,busy=false;
function fmt(n){return '$ '+Number(n||0).toLocaleString('zh-TW');}
function status(msg,err){const e=$('wallet-status');if(!e)return;e.textContent=msg;e.classList.toggle('text-rose-600',!!err);e.classList.toggle('text-slate-500',!err);}
function authButtons(){if($('wallet-login'))$('wallet-login').hidden=!!user;if($('wallet-logout'))$('wallet-logout').hidden=!user;}
function actions(){const enabled=!!user&&REMOTE&&!!service;document.querySelectorAll('[data-wallet-write]').forEach(b=>b.disabled=!enabled||busy);if($('wallet-initial-funding-button')){const exists=!!(state&&state.transactions.some(t=>t.type==='initial_funding'));$('wallet-initial-funding-button').hidden=!enabled||exists;$('wallet-initial-funding-button').disabled=!enabled||busy;}}
function text(tag,cls,value){const e=document.createElement(tag);e.className=cls||'';e.textContent=value==null?'':String(value);return e;}
function clear(msg){state=null;['wallet-total-balance','wallet-cumulative-savings','wallet-month-income','wallet-month-expense','fund-snack','fund-general','fund-allowance','dash-total-asset','fulfill-available-balance'].forEach(id=>{if($(id))$(id).textContent='—';});['wallet-logs-list','ledger-records-container','dash-recent-transactions'].forEach(id=>{if($(id))$(id).replaceChildren(text('p','py-4 text-center text-slate-400',msg));});actions();}
function funds(t){const rows=(t.entries||[]).map(e=>FUND[e.fundType]+' '+(Number(e.delta)>0?'+':'')+Number(e.delta)+'（'+Number(e.balanceBefore)+'→'+Number(e.balanceAfter)+'）');if(rows.length)return rows.join('、');return Object.entries(t.allocations||{}).filter(x=>Number(x[1])!==0).map(x=>FUND[x[0]]+' '+(Number(x[1])>0?'+':'')+Number(x[1])).join('、')||'無資金分錄';}
function row(t,compact){const r=document.createElement('div');r.className=compact?'py-2 flex items-center justify-between gap-3 border-b border-slate-50':'p-3 flex items-center justify-between gap-3 hover:bg-rose-50/40 transition';const l=document.createElement('div');l.className='min-w-0 flex-1';l.appendChild(text('p','font-bold text-slate-700 truncate',t.note||TYPE[t.type]||'帳務交易'));l.appendChild(text('p','text-[10px] text-slate-400 mt-0.5',String(t.occurredAt||'').slice(0,10)+' · '+(TYPE[t.type]||t.type)+' · '+funds(t)));const meta=[t.sourceType&&t.sourceId?'來源 '+t.sourceType+':'+t.sourceId:'',t.correctionEvent?'更正第 '+t.correctionEvent.correctionNo+' 次：'+t.correctionEvent.reason:''].filter(Boolean).join(' · ');if(meta)l.appendChild(text('p','text-[10px] text-slate-400 mt-0.5',meta));const q=document.createElement('div');q.className='text-right shrink-0';const sign=['income','initial_funding','refund','scoreboard_snack'].includes(t.type)?'+':t.type==='expense'?'-':'';q.appendChild(text('p','font-extrabold '+(sign==='+'?'text-emerald-600':sign==='-'?'text-rose-600':'text-slate-700'),sign+'$'+Number(t.amount||0).toLocaleString('zh-TW')));q.appendChild(text('p','text-[10px] text-slate-400',t.id));r.append(l,q);return r;}
function renderWallet(){if(!state){clear('錢包資料尚未載入；不顯示原型假資料。');return;}const s=Adapter.summarize(state,new Date());if($('wallet-total-balance'))$('wallet-total-balance').textContent=fmt(s.totalAssets);if($('wallet-cumulative-savings'))$('wallet-cumulative-savings').textContent=fmt(s.cumulativeSavings);['snack','general','allowance'].forEach(k=>{if($('fund-'+k))$('fund-'+k).textContent=fmt(state.balances[k]);});if($('wallet-month-income'))$('wallet-month-income').textContent='+$'+s.income.toLocaleString('zh-TW');if($('wallet-month-expense'))$('wallet-month-expense').textContent='-$'+s.expense.toLocaleString('zh-TW');if($('dash-total-asset'))$('dash-total-asset').textContent=fmt(s.totalAssets);if($('fulfill-available-balance'))$('fulfill-available-balance').textContent=fmt(s.totalAssets);const logs=$('wallet-logs-list');if(logs){logs.replaceChildren();const f=typeof walletFilter!=='undefined'?walletFilter:'all',items=state.transactions.filter(t=>f==='all'||t.type===f);if(!items.length)logs.appendChild(text('p','py-4 text-center text-slate-400','目前沒有帳務交易紀錄'));else items.forEach(t=>logs.appendChild(row(t,true)));}const recent=$('dash-recent-transactions');if(recent){recent.replaceChildren();state.transactions.slice(0,3).forEach(t=>recent.appendChild(row(t,true)));if(!state.transactions.length)recent.appendChild(text('p','py-3 text-center text-slate-400','目前沒有帳務交易紀錄'));}actions();}
function renderLedger(){const box=$('ledger-records-container');if(!box)return;box.replaceChildren();if(!state){box.appendChild(text('p','py-6 text-center text-slate-400','帳務資料尚未啟用；目前不顯示原型假資料。'));return;}const q=($('ledger-search-input')?.value||'').trim().toLocaleLowerCase(),f=$('ledger-filter-fund')?.value||'all',ty=$('ledger-filter-type')?.value||'all',items=state.transactions.filter(t=>String(t.note||'').toLocaleLowerCase().includes(q)&&(ty==='all'||t.type===ty)&&(f==='all'||Object.keys(t.allocations||{}).includes(f)));if(!items.length)box.appendChild(text('p','py-6 text-center text-slate-400','查無對應的收支明細'));else items.forEach(t=>box.appendChild(row(t,false)));}
async function load(){if(!user){clear('請先登入孩子帳戶，才可讀取專屬錢包。');return;}if(!REMOTE){status('已登入；錢包讀寫暫停，等待隔離資料庫驗證與啟用授權。');clear('接線已完成；資料庫尚未啟用，不讀取正式資料庫，也不顯示 Mock Data。');return;}if(busy)return;busy=true;actions();status('正在讀取錢包帳務…');try{const tx=await service.getTransactions(200),ids=tx.map(x=>x.id),res=await Promise.all([service.getAccounts(),service.getEntries(ids),service.getCorrectionEvents(ids)]);state=Adapter.normalizeWalletData(res[0],tx,res[1],res[2]);status('已登入：'+(user.email||user.id)+'｜錢包資料已同步');renderWallet();renderLedger();}catch(e){clear('錢包資料讀取失敗；請確認 Migration 與權限設定。');status('錢包資料讀取失敗：'+(e.message||'未知錯誤'),true);}finally{busy=false;actions();}}
function localToday(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function formMode(){const ty=$('ledger-type')?.value||'income',expense=ty==='expense',transfer=ty==='transfer',initial=ty==='initial_funding';if($('ledger-category-wrap'))$('ledger-category-wrap').hidden=!expense;if($('ledger-allocation-wrap'))$('ledger-allocation-wrap').hidden=!expense;if($('ledger-transfer-wrap'))$('ledger-transfer-wrap').hidden=!transfer;if($('ledger-income-hint'))$('ledger-income-hint').hidden=expense||transfer;if($('ledger-modal-title'))$('ledger-modal-title').textContent=initial?'首次初始建帳':expense?'新增支出':transfer?'資金用途轉換':'新增收入';if($('ledger-submit-label'))$('ledger-submit-label').textContent=initial?'建立初始餘額':transfer?'確認資金轉換':'儲存帳務交易';const g=$('ledger-alloc-general');if(g&&$('ledger-category')){g.disabled=$('ledger-category').value!=='non_food';if(g.disabled)g.value='0';}}
function openModal(ty){if(!user||!REMOTE){window.toggleToast('錢包尚未啟用資料庫接線，暫時不能新增帳務。');return;}if(ty==='initial_funding'&&state&&state.transactions.some(t=>t.type==='initial_funding')){window.toggleToast('初始建帳只能建立一次。');return;}$('ledger-form').reset();$('ledger-type').value=ty||'income';$('ledger-date').value=localToday();['snack','general','allowance'].forEach(k=>{if($('ledger-alloc-'+k))$('ledger-alloc-'+k).value='0';});formMode();$('modal-ledger').classList.remove('hidden');}
async function submit(e){e.preventDefault();if(!user||!REMOTE||!service){window.toggleToast('錢包尚未啟用，無法寫入帳務。');return;}const b=$('ledger-form').querySelector('button[type="submit"]');if(b)b.disabled=true;try{const op=Adapter.buildOperation({type:$('ledger-type').value,amount:$('ledger-amount').value,category:$('ledger-category')?.value,allocations:{snack:Number($('ledger-alloc-snack')?.value||0),general:Number($('ledger-alloc-general')?.value||0),allowance:Number($('ledger-alloc-allowance')?.value||0)},sourceFund:$('ledger-transfer-source')?.value,targetFund:$('ledger-transfer-target')?.value,note:$('ledger-note').value,date:$('ledger-date').value,idempotencyKey:crypto.randomUUID()});await service.post(op);$('modal-ledger').classList.add('hidden');window.toggleToast('帳務交易已儲存。');await load();}catch(err){window.toggleToast(err.message||'帳務交易失敗，資料未更新。');}finally{if(b)b.disabled=false;actions();}}
function noDelete(){window.toggleToast('帳務原始交易不可直接刪除；退款或更正須依正式帳務流程處理。');}
function noWish(){window.toggleToast('願望扣款屬於 P2，尚未接線；目前不會變更錢包餘額。');}
async function init(){window.renderWallet=renderWallet;window.renderLedger=renderLedger;window.openLedgerModal=openModal;window.handleLedgerSubmit=submit;window.confirmDeleteLedger=noDelete;window.executeFulfillWish=noWish;window.openFulfillModal=noWish;window.getTotalAsset=()=>state?state.totalAssets:0;if($('ledger-type'))$('ledger-type').addEventListener('change',formMode);if($('ledger-category'))$('ledger-category').addEventListener('change',formMode);if(!config||!window.supabase||!Core||!Adapter){status('登入或錢包模組載入失敗，請檢查前端資源。',true);clear('錢包模組尚未載入。');return;}client=window.supabase.createClient(config.url,config.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});service=Core.createWalletService(client);if($('wallet-login'))$('wallet-login').addEventListener('click',async()=>{const r=await client.auth.signInWithOAuth({provider:'google',options:{redirectTo:config.redirectTo}});if(r.error)status('登入失敗：'+r.error.message,true);});if($('wallet-logout'))$('wallet-logout').addEventListener('click',async()=>{const r=await client.auth.signOut();if(r.error)status('登出失敗：'+r.error.message,true);});client.auth.onAuthStateChange((_e,s)=>{user=s&&s.user?s.user:null;authButtons();if(user)load();else{status('未登入｜請使用孩子帳戶登入');clear('請先登入孩子帳戶，才可讀取專屬錢包。');}});const r=await client.auth.getSession();if(r.error){status('登入狀態讀取失敗：'+r.error.message,true);return;}user=r.data.session?r.data.session.user:null;authButtons();if(user)await load();else{status('未登入｜請使用孩子帳戶登入');clear('請先登入孩子帳戶，才可讀取專屬錢包。');}actions();}
window.addEventListener('load',init,{once:true});
})();